const msg = $input.first().json.message;

let contentType = 'text';
let rawContent = '';
let photoFileId = null;
let caption = msg.caption || '';

if (msg.text) {
  const urlRegex = /(https?:\/\/[^\s]+)/g;
  const urls = msg.text.match(urlRegex);
  if (urls && urls.length > 0) {
    contentType = 'url';
    rawContent = urls[0];
  } else {
    contentType = 'text';
    rawContent = msg.text;
  }
} else if (msg.photo) {
  contentType = 'photo';
  photoFileId = msg.photo[msg.photo.length - 1].file_id;
  rawContent = caption;
} else if (msg.caption) {
  const urlRegex = /(https?:\/\/[^\s]+)/g;
  const urls = msg.caption.match(urlRegex);
  if (urls) {
    contentType = 'url';
    rawContent = urls[0];
  } else {
    contentType = 'text';
    rawContent = msg.caption;
  }
}

return [{
  json: {
    contentType,
    rawContent,
    photoFileId,
    caption,
    chatId: msg.chat.id,
    messageId: msg.message_id
  }
}];

const html = $input.first().json.data || String($input.first().json);
const sourceUrl = $('Router de Contenido').first().json.rawContent;
const chatId = $('Router de Contenido').first().json.chatId;

function stripHtml(html) {
  if (typeof html !== 'string') html = String(html);
  html = html.replace(/<script[\s\S]*?<\/script>/gi, '');
  html = html.replace(/<style[\s\S]*?<\/style>/gi, '');
  html = html.replace(/<nav[\s\S]*?<\/nav>/gi, '');
  html = html.replace(/<header[\s\S]*?<\/header>/gi, '');
  html = html.replace(/<footer[\s\S]*?<\/footer>/gi, '');

  const titleMatch = html.match(/<title[^>]*>([^<]+)<\/title>/i);
  const title = titleMatch ? titleMatch[1].trim() : '';

  const descMatch = html.match(/<meta[^>]*name=["']description["'][^>]*content=["']([^"']+)["']/i) ||
                    html.match(/<meta[^>]*content=["']([^"']+)["'][^>]*name=["']description["']/i);
  const metaDesc = descMatch ? descMatch[1].trim() : '';

  const ogImageMatch = html.match(/<meta[^>]*property=["']og:image["'][^>]*content=["']([^"']+)["']/i) ||
                       html.match(/<meta[^>]*content=["']([^"']+)["'][^>]*property=["']og:image["']/i);
  const featuredImage = ogImageMatch ? ogImageMatch[1].trim() : '';

  const paragraphs = (html.match(/<p[^>]*>[\s\S]*?<\/p>/gi) || [])
    .map(p => p.replace(/<[^>]+>/g, '').trim())
    .filter(p => p.length > 40)
    .slice(0, 8);

  return { title, metaDesc, bodyText: paragraphs.join('\n\n'), featuredImage };
}

const extracted = stripHtml(html);

let source = 'General';
if (sourceUrl.includes('distritointerior')) source = 'Distrito Interior';
else if (sourceUrl.includes('diariodemocracia')) source = 'Diario Democracia';
else if (sourceUrl.includes('facebook.com')) source = 'Facebook';
else if (sourceUrl.includes('infobae')) source = 'Infobae';
else if (sourceUrl.includes('clarin')) source = 'Clarín';

return [{
  json: {
    title: extracted.title,
    metaDesc: extracted.metaDesc,
    bodyText: extracted.bodyText,
    featuredImage: extracted.featuredImage,
    sourceUrl,
    source,
    rawNewsText: `TÍTULO: ${extracted.title}\n\nDESCRIPCIÓN: ${extracted.metaDesc}\n\nCONTENIDO:\n${extracted.bodyText}`,
    chatId,
    contentType: 'url'
  }
}];

const fileData = $input.first().json;
const routerData = $('Router de Contenido').first().json;

const filePath = fileData.result?.file_path || '';
const photoUrl = `https://api.telegram.org/file/bot{{ TU_BOT_TOKEN }}/${filePath}`;

return [{
  json: {
    title: routerData.caption || 'Noticia enviada por Telegram',
    metaDesc: routerData.caption || '',
    bodyText: routerData.caption || '',
    featuredImage: photoUrl,
    externalPhotoUrl: photoUrl,
    source: 'WhatsApp / Telegram',
    sourceUrl: '',
    rawNewsText: routerData.caption || 'Ver imagen adjunta',
    chatId: routerData.chatId,
    contentType: 'photo'
  }
}];

const data = $input.first().json;
return [{
  json: {
    title: data.rawContent.substring(0, 100),
    metaDesc: '',
    bodyText: data.rawContent,
    featuredImage: '',
    source: 'Redacción propia',
    sourceUrl: '',
    rawNewsText: data.rawContent,
    chatId: data.chatId,
    contentType: 'text'
  }
}];

