const gptResponse = $input.first().json;
const previousData = $('Unificar Contenido').first().json;

let newsData = {};
try {
  const content = gptResponse.choices[0].message.content;
  newsData = JSON.parse(content);
} catch(e) {
  newsData = {
    titulo: previousData.title || 'Noticia de General Pinto',
    copete: previousData.metaDesc || '',
    cuerpo: previousData.bodyText || previousData.rawNewsText || '',
    caption_instagram: `📰 ${previousData.title}\n\n${previousData.metaDesc}\n\n#GeneralPinto #Noticias #BsAs`,
    caption_facebook: `${previousData.title}\n\n${(previousData.bodyText || '').substring(0, 300)}`,
    caption_tiktok: `🗞️ ${(previousData.title || '').substring(0, 100)} #GeneralPinto #Noticias`,
    prompt_imagen: `Professional news photo related to: ${previousData.title}. Argentina, photorealistic style.`,
    categoria: 'Sociedad',
    hashtags: ['GeneralPinto', 'Noticias', 'BsAs', 'Argentina']
  };
}

return [{
  json: {
    ...newsData,
    featuredImage: previousData.featuredImage || '',
    externalPhotoUrl: previousData.externalPhotoUrl || '',
    sourceUrl: previousData.sourceUrl || '',
    source: previousData.source || '',
    chatId: previousData.chatId,
    contentType: previousData.contentType,
    timestamp: new Date().toISOString()
  }
}];

const allInputs = $input.all();
const gptData = $('Procesar Respuesta GPT-4o').first().json;

let generatedImageUrl = '';
for (const item of allInputs) {
  if (item.json?.data?.[0]?.url) {
    generatedImageUrl = item.json.data[0].url;
    break;
  }
}

const finalImageUrl = generatedImageUrl || 
                      gptData.externalPhotoUrl || 
                      gptData.featuredImage || 
                      '';

return [{
  json: {
    ...gptData,
    finalImageUrl,
    imageSource: generatedImageUrl ? 'dall-e' : (gptData.externalPhotoUrl ? 'telegram' : 'article')
  }
}];

const newsData = $('Unificar Imagen Final').first().json;
const igResult = $('Blotato: Publicar Instagram').first().json;
const fbResult = $('Blotato: Publicar Facebook').first().json;
const ttResult = $('Blotato: Publicar TikTok').first().json;

const igOk = igResult?.id || igResult?.success ? '✅ Instagram: Publicado' : '❌ Instagram: Error';
const fbOk = fbResult?.id || fbResult?.success ? '✅ Facebook: Publicado' : '❌ Facebook: Error';
const ttOk = ttResult?.id || ttResult?.success ? '✅ TikTok: Publicado' : '❌ TikTok: Error';

const hora = new Date().toLocaleString('es-AR', { timeZone: 'America/Argentina/Buenos_Aires' });

const msg = `🗞️ *Portal General Pinto*\n\n📰 *${newsData.titulo}*\n📂 ${newsData.categoria} · ${newsData.source}\n\n*Publicado en:*\n${igOk}\n${fbOk}\n${ttOk}\n\n⏰ ${hora}`;

return [{
  json: {
    chatId: newsData.chatId,
    message: msg
  }
}];
